import { h, render, Component } from 'preact';

class MenuLateral extends Component {

  constructor(props) {
    super(props);
  }

  componentDidMount() {
    
  }

  handleChangeMatrix(value) {
    let self = this;

    let fn = (evt) => {
      evt.preventDefault();

      let o = self.props.o;
      if (o) {
        let matrices = o.matrices_;
        if (!matrices) matrices = [];

        for (let i = 0; i < matrices.length; i++) {
          let m = matrices[i];
          if (m.id == value) {
            let s = m.structure;

            /*self.setState({ matrix: m, structure: s }, () => {
              $('.button_menu').sideNav('hide');
            });*/

            self.props.onChangeMatrix(m, s);

            break;
          }
        }
      }
    };

    return fn;

    /*let fn = (evt) => {
      let value = evt.target.value;
      if (value != '') {
        value = parseInt(value);

        let matrices = self.state.matrices_;
        for (let i = 0; i < matrices.length; i++) {
          let m = matrices[i];
          if (m.id == value) {
            let s = m.structure;
            self.setState({ structure: s });
            
            break;
          }
        }
      }
    };*/
  }

  handleItemGroup(group) {
    let self = this;

    let fn = (evt) => {
      evt.preventDefault();
      evt.stopPropagation();

      /*self.setState({ structure: [group] }, () => {
        $('.button_menu').sideNav('hide');
      });*/

      let structure = [group];
      self.props.onItemGroup(structure);
    };

    return fn;
  }

  handleRestoreMatrix() {
    let self = this;

    let fn = (evt) => {
      evt.preventDefault();

      let o = self.props.o;
      if (o) {
        let m = o.matrix;
        if (m) {
          if (!m.structure) m.structure = [];

          let structure = m.structure;
          //self.setState({ structure: structure });
        
          self.props.onRestoreMatrix(structure);
        }
      }
    };

    return fn;
  }

  createItemMatrix() {
    let self = this;

    let fn = (item, index) => {
      return (
        <span key={item.id} style="color: #888;">
          <a href="#" onClick={self.handleChangeMatrix(item.id)}>{item.name}</a>
        </span>
      );
    };

    return fn;
  }

  createItemGroup() {
    let self = this;

    let fn = (item, index) => {
      if (!item.sons) item.sons = [];

      return (
        <li>
          <div className="collapsible-header">
            <div className="col s2">
              <img src="/static/images/macropera.svg" width="28" alt="" style="vertical-align: middle;" />
            </div>
            <div className="col s10 txt"
              style="font-size: 1.4em; margin-left: 0.4em;font-weight: 200;"
              onClick={this.handleItemGroup(item)}
            >
              {item.name}
            </div>
          </div>
          <div className="collapsible-body" style="display: none;">
            {item.sons.map(this.createItemGroup())}
          </div>
        </li>
      );
    };

    return fn;
  }

  render(props, state) {
    let o = props.o;

    if (!o) {
      o = {
        matrices_: [],
        matrix: {
          name: 'N/A',
          structure: [],
        }
      };
    }

    return (
      <ul id="barra_macrop" className="side-nav side_macrop">
        <li>
          <div className="user-view">
            <div className="background">
              <img src="/static/images/sidebar.jpg" />
            </div>
          </div>
        </li>
        <li>
          <ul className="collapsible collapsible-accordion" data-collapsible="accordion">
            <li>
              <div className="collapsible-header">
                <div className="col s12 txt" style="font-size: 1.4em; margin-left: 0.4em;font-weight: 200;">
                  Matrices
                </div>
              </div>
              <div className="collapsible-body" style="display: none;">
                {o.matrices_.map(this.createItemMatrix())}
              </div>
            </li>
          </ul>
        </li>
        <li>
          <br />
        </li>
        <li onClick={this.handleRestoreMatrix()}>
          {o.matrix.name}
        </li>
        <li>
          <ul className="collapsible collapsible-accordion" data-collapsible="accordion">
            {o.matrix.structure.map(this.createItemGroup())}
          </ul>
        </li>
      </ul>      
    );
  }
}

export default MenuLateral;