import { h, render, Component } from 'preact';
import { w3cwebsocket } from 'websocket';
import { isNumber, isString } from 'underscore';

import Header from './../header.jsx';
import constants from './../constants.js';

const wsURL = `ws://${URLWSR}/ws`;

const DIARY   = 'diary';
const MONTHLY = 'monthly';
const ANNUAL  = 'annual';
const CUSTOM  = 'custom';

const MINUTE = 'minute';
const HOUR = 'hour';
const DAY = 'day';

class Content extends Component {

  constructor() {
    super();

    this.state = {
      reports_: [],
    };
  }

  componentDidMount() {
    this.getReports();

    this.serviceWSR();
  }

  initializePickers() {
    $('.timepicker').pickatime({
      default: 'now',
      fromnow: 0,
      twelvehour: false,
      donetext: 'OK',
      cleartext: 'Limpiar',
      canceltext: 'Cancelar',
      autoclose: false,
      ampmclickable: true
    });

    $('.datepicker').pickadate({
      selectMonths: true,
      selectYears: 15,
      format: 'dd-mm-yyyy',
      today: 'Hoy',
      clear: 'Limpiar',
      close: 'Ok',
      closeOnSelect: true,
      monthsFull: ['Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio', 'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre'],
      monthsShort: ['Ene', 'Feb', 'Mar', 'Abr', 'May', 'Jun', 'Jul', 'Ago', 'Sep', 'Oct', 'Nov', 'Dic'],
      weekdaysShort: ['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'],
      weekdaysFull: ['Domingo', 'Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes', 'Sabado'],
      weekdaysLetter: ['D', 'L', 'M', 'M', 'J', 'V', 'S'],
    });    
  }

  getReports() {
    let self = this;

    let url = `${constants.URL_SERVER_REPORTS}/list`;

    let xhr = $.ajax({
      url: url,
      type: constants.METHOD_GET,
      dataType: constants.JSON,
    });

    xhr.done((res, status, response) => {
      if (response.status == constants.STATUS_OK) {
        self.setState({ reports_: res.docs }, () => {
          $('select').material_select();
          self.initializePickers();
        });

      } else if (response.status == constants.STATUS_ACCEPTED) {
        alert(res.message);
      }
    });

    xhr.fail((res, status, respose) => {
      if (res.responseJSON) {
        let json = res.responseJSON;
        alert(json.message);
      } else {
        alert(constants.MESSAGE_ERROR);
      }
    });
  }

  serviceWSR() {
    let self = this;

    this.ws = new w3cwebsocket(wsURL, constants.TTX_PROTOCOOL);

    this.ws.onerror = () => {
      console.log('WSR: connection Error');
    };

    this.ws.onopen = (evt) => {
      console.log('WSR connected');
    };

    this.ws.onclose = (evt) => {
      console.log('WSR closed');

      setTimeout(() => {
        self.serviceWSR();
      }, 1000);
    }

    this.ws.onmessage = (evt) => {
      let s = evt.data;
      try {
        let o = JSON.parse(s);
        if (o.err) {
          alert(o.message);

          return;
        }

        console.log(o);

        if (o.EVENT_RESPONSE_REPORT) {
          console.log(o.content);
        }

      } catch(e) {
        console.log('WSR.ERROR: JSON.parse', s);
      }
    };
  }

  parseDate(s) {
    if (s) {
      if (isString(s)) {
        let elements = s.split('-');
        elements = elements.reverse();

        let value = '';
        for (let i = 0; i < elements.length; i++) {
          const element = elements[i];
          if (i == 0) {
            value = `${element}`;
          } else {
            value = `${value}-${element}`;
          }
        }

        return value;
      }
    }

    return s;
  }

  handleGoConfigurations() {
    let self = this;

    let fn = (evt) => {
      evt.preventDefault();
      evt.stopPropagation();

      location.href = '/configuration/matrices';
    };

    return fn;
  }

  handleCreate(value) {
    let self = this;

    let fn = (evt) => {
      evt.preventDefault();

      if (value == DIARY) {
        let linkDiary = document.querySelector('#link-report-diary');
        let inputReport = document.querySelector('#input-d-report');
        let inputDate = document.querySelector('#input-d-date');

        linkDiary.style.display = 'none';

        let sId = inputReport.value.trim();
        if (sId == '') return;

        let date = inputDate.value.trim();
        if (date == '') return;      

        let report_id = parseInt(sId)
        if (!isNumber(report_id)) return

        date = self.parseDate(date);

        let content = {
          report_id: report_id,
          date_of: date,
          report: DIARY
        };

        let o = {
          evt: constants.EVENT_REQUEST_REPORT,
          content: content
        }        

        console.log("REQ: ", o);

        if (self.ws) {
          let msg = JSON.stringify(o);
          self.ws.send(msg);
        }

      } else if (value == MONTHLY) {
        let linkMonthly = document.querySelector('#link-report-monthly');
        let inputReport = document.querySelector('#input-m-report');
        let inputDateOf = document.querySelector('#input-m-date-of');
        let inputDateTo = document.querySelector('#input-m-date-to');

        linkMonthly.style.display = 'none';

        let sId = inputReport.value.trim();
        if (sId == '') return;

        let dateOf = inputDateOf.value.trim();
        if (dateOf == '') return;

        let dateTo = inputDateTo.value.trim();
        if (dateTo == '') return;        

        let report_id = parseInt(sId)
        if (!isNumber(report_id)) return
        
        dateOf = self.parseDate(dateOf);
        dateTo = self.parseDate(dateTo);

        let content = {
          report_id: report_id,
          date_of: dateOf,
          date_to: dateTo,
          report: MONTHLY
        };

        let o = {
          evt: constants.EVENT_REQUEST_REPORT,
          content: content
        }

        console.log("REQ: ", o);

        if (self.ws) {
          let msg = JSON.stringify(o);
          self.ws.send(msg);
        }

      } else if (value == ANNUAL) {
        let linkAnnual = document.querySelector('#link-report-monthly');
        let inputReport = document.querySelector('#input-a-report');
        let inputYear = document.querySelector('#input-a-year');

        linkAnnual.style.display = 'none';

        let sId = inputReport.value.trim();
        if (sId == '') return;

        let sYear = inputYear.value.trim();
        if (sYear == '') return;

        let report_id = parseInt(sId)
        if (!isNumber(report_id)) return

        let year = parseInt(sYear)
        if (!isNumber(year)) return        

        let content = {
          report_id: report_id,
          year: year,
          report: ANNUAL
        };

        let o = {
          evt: constants.EVENT_REQUEST_REPORT,
          content: content
        }

        console.log("REQ: ", o);

        if (self.ws) {
          let msg = JSON.stringify(o);
          self.ws.send(msg);
        }

      } else if (value == CUSTOM) {
        let linkCustom = document.querySelector('#link-report-custom');
        let inputReport = document.querySelector('#input-c-report');
        let inputDateOf = document.querySelector('#input-c-date-of');
        let inputDateTo = document.querySelector('#input-c-date-to');
        let inputTimeOf = document.querySelector('#input-c-time-of');
        let inputTimeTo = document.querySelector('#input-c-time-to');        
        let inputType = document.querySelector('#input-c-type');

        linkCustom.style.display = 'none';

        let sId = inputReport.value.trim();
        if (sId == '') return;

        let dateOf = inputDateOf.value.trim();
        if (dateOf == '') return;

        let dateTo = inputDateTo.value.trim();
        if (dateTo == '') return;

        let timeOf = inputTimeOf.value.trim();
        if (timeOf == '') return;

        let timeTo = inputTimeTo.value.trim();
        if (timeTo == '') return;        

        let type = inputType.value.trim();
        if (type == '') return;                

        let report_id = parseInt(sId)
        if (!isNumber(report_id)) return

        dateOf = self.parseDate(dateOf);
        dateTo = self.parseDate(dateTo);

        let content = {
          report_id: report_id,
          date_of: `${dateOf} ${timeOf}:00`,
          date_to: `${dateTo} ${timeTo}:00`,
          type: type,
          report: CUSTOM
        };

        let o = {
          evt: constants.EVENT_REQUEST_REPORT,
          content: content
        }

        console.log("REQ: ", o);

        if (self.ws) {
          let msg = JSON.stringify(o);
          self.ws.send(msg);
        }
      }

    };

    return fn;
  }

  createOptReport() {
    let self = this;

    let fn = (item, index) => {
      return <option key={index} value={item.id}>{item.name}</option>;
    };

    return fn;
  }

  render(props, state) {
    return (
      <div>
        <Header module={constants.REPORTS_MODULE} />

        <section className="matriz_simplificada">
          <div className="row">
            <div className="col s12 m12 body_int">
              <div className="thumb_matriz">

                <ul className="collapsible" data-collapsible="accordion">
                  <li>
                    <div className="collapsible-header">Reporte Diario</div>
                    <div className="collapsible-body">
                      <div className="row">
                        <div className="col s3"></div>
                        <div className="col s6">
                          <form onSubmit={this.handleCreate(DIARY)} >

                            <div className="input-field col s12">
                              <select id="input-d-report">
                                <option value="" disabled selected>Reporte</option>
                                {state.reports_.map(this.createOptReport())}
                              </select>
                              <label htmlFor="input-d-report">Reporte</label>
                            </div>

                            <div className="input-field col s12">
                              <label htmlFor="input-d-date">Fecha</label>
                              <input type="text" id="input-d-date" className="datepicker" />
                            </div>

                            <div className="col s6">
                              <button className="btn waves-effect waves-light green" type="submit">
                                Generar <i className="material-icons right">send</i>
                              </button>
                            </div>
                            <div className="col s6">
                              <a id="link-report-diary" className="waves-effect waves-light blue btn" href="#">
                                Descargar
                            <i className="material-icons right">file_download</i>
                              </a>
                            </div>

                          </form>
                        </div>
                        <div className="col s3"></div>
                      </div>
                    </div>
                  </li>
                  <li>
                    <div className="collapsible-header">Reporte Personalizado</div>
                    <div className="collapsible-body">
                      <div className="row">
                        <div className="col s3"></div>
                        <div className="col s6">
                          <form onSubmit={this.handleCreate(CUSTOM)} >

                            <div className="input-field col s12">
                              <select id="input-c-report">
                                <option value="" disabled selected>Reporte</option>
                                {state.reports_.map(this.createOptReport())}
                              </select>
                              <label htmlFor="input-c-report">Reporte</label>
                            </div>

                            <div className="input-field col s6">
                              <label htmlFor="input-c-date-of">Fecha de</label>
                              <input type="text" id="input-c-date-of" className="datepicker" />
                            </div>

                            <div className="input-field col s6">
                              <label htmlFor="input-c-time-of">Hora de</label>
                              <input type="text" id="input-c-time-of" className="timepicker" />
                            </div>

                            <div className="input-field col s6">
                              <label htmlFor="input-c-date-to">A</label>
                              <input type="text" id="input-c-date-to" className="datepicker" />
                            </div>

                            <div className="input-field col s6">
                              <label htmlFor="input-c-time-to">Hora de</label>
                              <input type="text" id="input-c-time-to" className="timepicker" />
                            </div>

                            <div className="input-field col s12">
                              <select id="input-c-type">
                                <option value="" disabled selected>Tipo</option>
                                <option value={MINUTE}>Minuto</option>
                                <option value={HOUR}>Hora</option>
                                <option value={DAY}>Día</option>
                              </select>
                              <label htmlFor="input-c-type">Tipo</label>                              
                            </div>

                            <div className="col s6">
                              <button className="btn waves-effect waves-light green" type="submit">
                                Generar <i className="material-icons right">send</i>
                              </button>
                            </div>
                            <div className="col s6">
                              <a id="link-report-custom" className="waves-effect waves-light blue btn" href="#">
                                Descargar
                                <i className="material-icons right">file_download</i>
                              </a>
                            </div>

                          </form>
                        </div>
                        <div className="col s3"></div>
                      </div>
                    </div>
                  </li>
                  <li>
                    <div className="collapsible-header">Reporte Mensual</div>
                    <div className="collapsible-body">
                      <div className="row">
                        <div className="col s3"></div>
                        <div className="col s6">
                          <form onSubmit={this.handleCreate(MONTHLY)} >

                            <div className="input-field col s12">
                              <select id="input-m-report">
                                <option value="" disabled selected>Reporte</option>
                                {state.reports_.map(this.createOptReport())}
                              </select>
                              <label htmlFor="input-m-report">Reporte</label>
                            </div>

                            <div className="input-field col s12">
                              <label htmlFor="input-m-date">Fecha de</label>
                              <input id="input-m-date-of" className="datepicker" type="text" />
                            </div>

                            <div className="input-field col s12">
                              <label htmlFor="input-m-date">A</label>
                              <input id="input-m-date-to" className="datepicker" type="text" />
                            </div>

                            <div className="col s6">
                              <button className="btn waves-effect waves-light green" type="submit">
                                Generar <i className="material-icons right">send</i>
                              </button>
                            </div>
                            <div className="col s6">
                              <a id="link-report-monthly" className="waves-effect waves-light blue btn" href="#">
                                Descargar
                                <i className="material-icons right">file_download</i>
                              </a>
                            </div>

                          </form>
                        </div>
                        <div className="col s3"></div>
                      </div>
                    </div>
                  </li>
                  <li>
                    <div className="collapsible-header">Reporte Anual</div>
                    <div className="collapsible-body">
                      <div className="row">
                        <div className="col s3"></div>
                        <div className="col s6">
                          <form onSubmit={this.handleCreate(ANNUAL)} >

                            <div className="input-field col s12">
                              <select id="input-a-report">
                                <option value="" disabled selected>Reporte</option>
                                {state.reports_.map(this.createOptReport())}
                              </select>
                              <label htmlFor="input-a-report">Reporte</label>
                            </div>

                            <div className="input-field col s12">
                              <select id="input-a-year">
                                <option value="" disabled selected>Año</option>
                                <option>2017</option>
                                <option>2018</option>
                                <option>2019</option>
                                <option>2020</option>
                              </select>
                              <label htmlFor="input-a-year">Año</label>                              
                            </div>

                            <div className="col s6">
                              <button className="btn waves-effect waves-light green" type="submit">
                                Generar <i className="material-icons right">send</i>
                              </button>
                            </div>
                            <div className="col s6">
                              <a id="link-report-annual" className="waves-effect waves-light blue btn" href="#">
                                Descargar
                                <i className="material-icons right">file_download</i>
                              </a>
                            </div>
                          </form>
                        </div>
                        <div className="col s3"></div>
                      </div>
                    </div>
                  </li>
                </ul>
                
              </div>
            </div>
          </div>
        </section>
      </div>
    );

  }
}

render(<Content />, document.getElementById('content-main'));