import { h, render, Component } from 'preact';

import MenuLateralMatrix from './matrix_module/menu-lateral.jsx';

import constants from './constants';

const PROFILE = 1;
const CONFIGURATION = 2;
const LOGOUT = 3;

class Header extends Component {

  constructor(props) {
    super(props);

    this.state = {
      notifications_: []
    };
  }

  componentDidMount() {
    $('.button_menu').sideNav({
      menuWidth: 265,
      edge: 'left',
      closeOnClick: true,
      draggable: true
    });


    $('.button-notifications').sideNav({
      menuWidth: 300,
      edge: 'right',
      closeOnClick: true,
      draggable: true,
    });    
  }

  handleRedirect(value) {
    let self = this;

    let fn = (evt) => {
      evt.preventDefault();

      if (value == PROFILE) {
        location.href = '/'
      } else if (value == CONFIGURATION) {
        location.href = '/configuration';
      } else if (value == LOGOUT) {
        location.href = `${constants.URL_SERVER_AUTH}/logout`;
      }
    };

    return fn;
  }

  handleRemoveNotification() {
    let self = this;

    let fn = (id) => {
      let notifications_ = self.state.notifications_;
      for (let i = 0; i < notifications_.length; i++) {
        const n = notifications_[i];
        if (n) {
          let n_id = n.id;
          if (n_id == id) {
            notifications_.splice(i, 1);
            self.setState({ notifications: notifications_ });

            break;
          }
        }
      }
    };

    return fn;
  }

  createItemNotification() {
    let self = this;

    let fn = (item, index) => {
      return <NotificationItem notifation={item} onRemove={this.handleRemoveNotification()} />
    };

    return fn;
  }

  /* Header: Matriz */
  handleRestoreMatrix() {
    let self = this;

    let fn = (structure) => {
      self.setState({ structure: structure });
    };

    return fn;
  }

  handleItemGroup() {
    let self = this;

    let fn = (structure) => {
      self.setState({ structure: structure }, () => {
        $('.button_menu').sideNav('hide');
      });
    };

    return fn;
  }

  handleChangeMatrix() {
    let self = this;

    let fn = (m, s) => {
      self.setState({ matrix: m, structure: s }, () => {
        $('.button_menu').sideNav('hide');
        let f = self.props.onChangeMatrix;
        if (f) {
          f(m, s);
        }
      });
    };

    return fn;
  }
  /* Header: Matriz */

  render(props, state) {
    let user = {
      email: constants.NA,
      name: constants.NA,
      role_out: constants.NA
    };

    if (props.user) {
      user = props.user;
    }

    let module = this.props.module;
    let menuLateral = false;

    if (module == constants.MATRIX_MODULE) {
      let o = props.o;

      menuLateral = <MenuLateralMatrix o={o} 
                      onRestoreMatrix={this.handleRestoreMatrix()}
                      onItemGroup={this.handleItemGroup()} 
                      onChangeMatrix={this.handleChangeMatrix()} />;
    }

    return (
      <header>
        <div className="topmenu">
          <div className="row">
            <div className="pemex_contrato">
              <ul>
                <li>
                  <img src="/static/images/logo_pemex.svg" alt="" />
                </li>
                <li>
                  <a href="#">
                    <p>
                      Grupo Multidisciplinario de Mantenimiento a Equipo Dinámico.
                      <br />
                      Activo de Producción Samaria - Luna
                      <br />
                      <span>
                        Contrato: 425014831
                        <i className="material-icons left">keyboard_arrow_down</i>
                      </span>
                    </p>
                  </a>
                </li>
              </ul>
            </div>
            <div className="avatar">
              <ul>
                <li>
                  <div className="avatar_info">
                    <a data-activates="bar_config_menu" className="bar_config" href="#">
                      <img src="/static/images/avatar.png" alt="" />
                      <p>
                        {user.name}
                        <br />
                        <span>{user.role_out}</span>
                      </p>
                      <i className="material-icons">keyboard_arrow_down</i>
                    </a>
                  </div>
                </li>
                <li>
                  <img className="ttx_logo" src="/static/images/logo_ttx_black.svg" alt="" />
                </li>
              </ul>
            </div>
          </div>
        </div>

        <nav>
          <ul id="nav-mobile" className="left hide-on-med-and-down">
            <li>
              <a data-activates="barra_macrop" className="side_macrop button_menu" href="#">
                <i className="material-icons left">menu</i>
              </a>
            </li>
            <li>
              <a href="/matrix">
                <i className="material-icons left">dashboard</i>Matriz
                </a>
            </li>
            <li>
              <a href="/graphic">
                <i className="material-icons left">timeline</i>Gráfica
                </a>
            </li>
            <li>
              <a href="/reports">
                <i className="material-icons left">assessment</i>Reportes
                </a>
            </li>
            <li>
              <a href="/operations">
                <i className="material-icons left">assignment</i>Operaciones
              </a>
            </li>
            <li>
              <a href="/events">
                <i className="material-icons left">date_range</i>Eventos
                </a>
            </li>
            <li>
              <a href="/location">
                <i className="material-icons left">room</i>Ubicación
                </a>
            </li>
            <li>
              <a href="/locator">
                <i className="material-icons left">gps_fixed</i>Localizador
                </a>
            </li>
            <li>
              <a href="/explorer">
                <i className="material-icons left">pageview</i>Explorador
                </a>
            </li>
          </ul>

          <ul id="nav-mobile" className="right">
            <li>
              <a data-activates="bar_notific_menu" className="bar_notific button-notifications" href="#">
                <i className="material-icons left">chat_bubble</i>
                <span>{state.notifications_.length}</span>
              </a>
            </li>
            <li>
              <a className="modal-trigger" href="#cerrar_sesion">
                <i className="material-icons left">power_settings_new</i>
              </a>
            </li>
          </ul>

          <ul id="slide-out" className="side-nav">
            <li>
              <div className="user-view">
                <div className="background">
                  <img src="/static/images/sidebar.jpg" />
                </div>
              </div>
            </li>
            <li>
              <a className="subheader">Menu Principal</a>
            </li>
            <li>
              <a className="waves-effect" href="#!">Menu 1</a>
            </li>
          </ul>

          <a href="#" data-activates="slide-out" className="button-collapse">
            <i className="material-icons">menu</i>
          </a>

          <ul id="bar_config_menu" className="side-nav bar_config">
            <li>
              <div className="config">
                <div className="avatar_bar">
                  <img src="/static/images/avatar.png" />
                </div>
                <h6>{user.name}<br /><strong>{user.role_out}</strong></h6>
              </div>
            </li>
            <li>
              <br />
            </li>
            <li onClick={this.handleRedirect(PROFILE)}>
              <a href="#">
                <i className="material-icons left">edit</i>Editar Perfil
              </a>
            </li>
            <li onClick={this.handleRedirect(CONFIGURATION)}>
              <a href="#">
                <i className="material-icons left">settings</i>Configuraciones
              </a>
            </li>
            <li onClick={this.handleRedirect(LOGOUT)}>
              <a href="#">
                <i className="material-icons left">highlight_off</i>Cerrar Sesión
              </a>
            </li>
          </ul>

          <ul id="bar_notific_menu" className="side-nav bar_notific">
            {state.notifications_.map(this.createItemNotification())}
          </ul>

          {menuLateral}

        </nav>
      </header>      
    );
  } 
}

export default Header;